import { NgModule } from '@angular/core';
import { RouterModule, Routes } from '@angular/router';

const routes: Routes = [
  { path: '', redirectTo: 'home', pathMatch: 'full' },
  {
    path: 'home/:id',
    loadComponent: () =>
      import('../../components/home/presenthome/presenthome.component').then(
        (m) => m.PresenthomeComponent
      ),
  },
  {
    path: 'subtype/:id',
    loadComponent: () =>
      import('../../components/subtype/subtype.component').then(
        (m) => m.SubtypeComponent
      ),
  },
  {
    path: 'setup/:id',
    loadComponent: () =>
      import('../../components/setup/form/form.component').then(
        (m) => m.FormComponent
      ),
  },
  {
    path: 'createWitness/:id',
    loadComponent: () =>
      import(
        '../../components/witnessSchedule/create-schedule/create-schedule.component'
      ).then((m) => m.CreateScheduleComponent),
  },
  {
    path: 'schedule-list/:id',
    loadComponent: () =>
      import(
        '../../components/witnessSchedule/schedule-list/schedule-list.component'
      ).then((m) => m.ScheduleListComponent),
  },
  {
    path: 'choose-docs/:id',
    loadComponent: () =>
      import('../../components/choose-docs/choose-docs.component').then(
        (m) => m.ChooseDocsComponent
      ),
  },
  {
    path: 'core-case/:id',
    loadComponent: () =>
      import('../../components/core-case/core-case.component').then(
        (m) => m.CoreCaseComponent
      ),
  },
];

@NgModule({
  imports: [RouterModule.forChild(routes)],
  exports: [RouterModule],
})
export class PresentRoutingModule {}
